import std.io
import std.time

test "release order" {
    scope {
        let a = task effect io time {
            let _ = time.sleep(50)
            io.println("a")
        }
        let b = task effect io time {
            let _ = time.sleep(50)
            io.println("b")
        }
        advanceTime(50)
        let _ = a.await()
        let _ = b.await()
    }
    assert(true, "done")
}
